 "content": "def transform(grid):
    # Two frame segments mark directions; non-frame markers send colored rays
    # toward the nearest frame along their row or column.
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    colors = {v for row in grid for v in row}
    bg = max(colors, key=lambda v: sum(row.count(v) for row in grid))
    frame = next(v for v in colors if v != bg)
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color in (bg, frame):
                continue
            paths = []
            for dr, dc in ((0, -1), (0, 1), (-1, 0), (1, 0)):
                rr, cc = r + dr, c + dc
                path = []
                while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == bg:
                    path.append((rr, cc))
                    rr += dr
                    cc += dc
                if path and 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == frame:
                    paths.append(path)
            if paths:
                for y, x in min(paths, key=len):
                    out[y][x] = 1
                out[r][c] = 4
    # Paint rows occupied by a frame endpoint across the background region.
    for r in range(h):
        if grid[r][0] == frame and all(grid[r][c] == bg for c in range(1, w)):
            for c in range(1, w): out[r][c] = 1
        elif grid[r][w-1] == frame and all(grid[r][c] == bg for c in range(w-1)):
            for c in range(w-1): out[r][c] = 1
    return out
