 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    colors = {v for row in grid for v in row}
    bg = max(colors, key=lambda v: sum(row.count(v) for row in grid))
    frame = next((v for v in colors if v != bg), None)
    if frame is None:
        return out

    # Find contiguous frame segments along the four outer edges.
    segments = []
    for side in ('left', 'right', 'top', 'bottom'):
        n = h if side in ('left', 'right') else w
        vals = [grid[i][0 if side == 'left' else w-1] if side in ('left','right')
                else grid[0 if side == 'top' else h-1][i] for i in range(n)]
        i = 0
        while i < n:
            if vals[i] != frame:
                i += 1
                continue
            j = i
            while j + 1 < n and vals[j+1] == frame:
                j += 1
            segments.append((side, i, j))
            i = j + 1

    # For opposite edge runs of equal length, markers project a full stripe
    # onto the corresponding position in the paired segment.
    pairmap = {}
    for a, (s1, lo1, hi1) in enumerate(segments):
        for s2, lo2, hi2 in segments[a+1:]:
            if hi1-lo1 != hi2-lo2:
                continue
            if (s1, s2) in (('left','right'), ('right','left'), ('top','bottom'), ('bottom','top')):
                pairmap[(s1, lo1, hi1)] = (s2, lo2, hi2)
                pairmap[(s2, lo2, hi2)] = (s1, lo1, hi1)

    for r in range(h):
        for c in range(w):
            val = grid[r][c]
            if val in (bg, frame):
                continue
            side_seg = None
            if c not in (0, w-1):
                for seg in segments:
                    side, lo, hi = seg
                    if side in ('left','right') and lo <= r <= hi:
                        side_seg = seg
                        break
            if side_seg is None:
                continue
            side, lo, hi = side_seg
            # Paint from marker to its frame border, then change marker to 4.
            if side == 'left':
                for x in range(1, c):
                    if grid[r][x] == bg: out[r][x] = 1
            else:
                for x in range(c+1, w-1):
                    if grid[r][x] == bg: out[r][x] = 1
            out[r][c] = 4
            other = pairmap.get(side_seg)
            if other:
                oside, olo, ohi = other
                rr = olo + (r-lo)
                if oside == 'left':
                    for x in range(1, w): out[rr][x] = 1
                elif oside == 'right':
                    for x in range(w-1): out[rr][x] = 1
                elif oside == 'top':
                    for y in range(1, h): out[y][rr] = 1
                else:
                    for y in range(h-1): out[y][rr] = 1
    return out
