    bg = max(colors, key=lambda v: sum(row.count(v) for row in grid))
    frame = next((v for v in colors if v != bg), None)
    if frame is None:
        return out
    # Detect runs of the frame color on the outer edges.
    runs = {}
    for side in ('left', 'right'):
        col = 0 if side == 'left' else w - 1
        indices = [r for r in range(h) if grid[r][col] == frame]
        if indices:
            groups = []
            start = prev = indices[0]
            for i in indices[1:]:
                if i != prev + 1:
                    groups.append((start, prev))
                    start = i
                prev = i
            groups.append((start, prev))
            runs[side] = groups
    # Each stripe of the border color defines the rows where the stripe is sent across.
    for side, groups in runs.items():
        for lo, hi in groups:
            for r in range(lo, hi + 1):
                # extend stripe across the row; marker gets endpoint color 4
                markers = [c for c in range(w) if grid[r][c] not in (bg, frame)]
                if side == 'left':
                    end = min(markers) if markers else w - 1
                    for c in range(1, end):
                        out[r][c] = 1
                    if markers:
                        out[r][end] = 4
                else:
                    end = max(markers) if markers else 0
                    for c in range(w - 2, end, -1):
                        out[r][c] = 1
                    if markers:
                        out[r][end] = 4
            # Copy stripe to opposite side at corresponding rows, including rows
            # in a stripe that is isolated within the run.
            for r in range(lo, hi + 1):
