 "content": "def transform(grid):
    # The frame segments align across opposite edges. Each non-frame marker
    # colors a matching row across the opposite frame segment, while its own
    # row is filled from the frame toward the marker, which becomes 4.
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    frame = max((v for v in counts if v != bg), key=counts.get)

    def runs(vals):
        ans=[]; i=0
        while i<len(vals):
            if vals[i]!=frame: i+=1; continue
            j=i
            while j+1<len(vals) and vals[j+1]==frame: j+=1
            ans.append((i,j)); i=j+1
        return ans
    left=runs([grid[r][0] for r in range(h)])
    right=runs([grid[r][w-1] for r in range(h)])
    pairs=[(a,b) for a in left for b in right if a[1]-a[0]==b[1]-b[0]]
    for r in range(h):
        for c in range(w):
            if grid[r][c] in (bg,frame): continue
            match=None
            for a,b in pairs:
                if a[0]<=r<=a[1]: match=(a,b,True); break
                if b[0]<=r<=b[1]: match=(b,a,False); break
            if match is None: continue
            src,dst,on_left=match
            rr=dst[0]+r-src[0]
            # Pair stripe spans the row, leaving the frame endpoint untouched.
            if on_left:
                for x in range(1,w):
                    if grid[rr][x]==bg: out[rr][x]=1
                for x in range(1,c):
                    if grid[r][x]==bg: out[r][x]=1
            else:
                for x in range(w-1):
                    if grid[rr][x]==bg: out[rr][x]=1
                for x in range(c+1,w-1):
                    if grid[r][x]==bg: out[r][x]=1
            out[r][c]=4
    return out
